NEW_FILES = json.loads('{"configuration_browser.py": "\\"\\"\\"Single-operator browser approval. Disabled by default; no approval MCP tool.\\n\\nLocal SQLite and project_data require approved persistent storage before live use.\\nApproval authorizes configuration saving, not mapping or export.\\n\\"\\"\\"\\nfrom __future__ import annotations\\n\\nimport base64\\nimport hashlib\\nimport hmac\\nimport html\\nimport json\\nimport os\\nimport re\\nimport secrets\\nimport sqlite3\\nimport threading\\nimport time\\nfrom dataclasses import dataclass, field\\nfrom datetime import datetime, timezone\\nfrom pathlib import Path\\nfrom urllib.parse import parse_qs, urlsplit\\n\\nfrom starlette.concurrency import run_in_threadpool\\nfrom starlette.responses import HTMLResponse, JSONResponse, Response\\nfrom starlette.routing import Route\\n\\nimport crosswalk_configuration_save as local\\nfrom source_configuration_workflow import SourceReviewRequest, review_source_configuration\\n\\nID = re.compile(r\\"cr_[0-9a-f]{32}\\\\Z\\")\\nSCHEMA = \\"mapcp_browser_configuration_approval_v1\\"\\nMAX_BYTES = 4_000_000\\nMAX_REVIEWS = 64\\nTTL_SECONDS = 1800\\nHEADERS = {\\n    \\"Cache-Control\\": \\"no-store\\",\\n    \\"Content-Security-Policy\\": \\"default-src \'none\'; form-action \'self\'; frame-ancestors \'none\'; base-uri \'none\'\\",\\n    \\"X-Content-Type-Options\\": \\"nosniff\\",\\n    \\"Referrer-Policy\\": \\"no-referrer\\",\\n    \\"X-Frame-Options\\": \\"DENY\\",\\n}\\n_rate_lock = threading.Lock()\\n_failures = {}\\n\\n\\nclass ReviewError(ValueError):\\n    pass\\n\\n\\ndef require(condition, message):\\n    if not condition:\\n        raise ReviewError(message)\\n\\n\\ndef canonical(value):\\n    return json.dumps(value, sort_keys=True, separators=(\\",\\", \\":\\"),\\n                      ensure_ascii=True, allow_nan=False)\\n\\n\\ndef digest(value):\\n    return hashlib.sha256(canonical(value).encode()).hexdigest()\\n\\n\\n@dataclass(frozen=True)\\nclass Settings:\\n    origin: str\\n    username: str\\n    password: str = field(repr=False)\\n    signing_key: str = field(repr=False)\\n    state_dir: Path\\n\\n    @classmethod\\n    def from_env(cls):\\n        require(os.environ.get(\\"MAPCP_CONFIG_REVIEW_ENABLED\\") == \\"true\\",\\n                \\"Configuration review is disabled.\\")\\n        require(os.environ.get(\\"MAPCP_CONFIG_STORAGE_APPROVED\\") == \\"true\\",\\n                \\"Configuration storage has not been approved.\\")\\n        origin = os.environ.get(\\"MAPCP_CONFIG_REVIEW_ORIGIN\\", \\"\\")\\n        u = urlsplit(origin)\\n        require(u.scheme == \\"https\\" and u.netloc and not u.username\\n                and not u.password and u.path == \\"\\" and not u.query\\n                and not u.fragment, \\"An exact HTTPS review origin is required.\\")\\n        username = os.environ.get(\\"MAPCP_CONFIG_REVIEW_USER\\", \\"\\")\\n        password = os.environ.get(\\"MAPCP_CONFIG_REVIEW_PASSWORD\\", \\"\\")\\n        key = os.environ.get(\\"MAPCP_CONFIG_SIGNING_KEY\\", \\"\\")\\n        api = os.environ.get(\\"MAPCP_API_TOKEN\\", \\"\\")\\n        require(re.fullmatch(r\\"[A-Za-z0-9_-]{1,64}\\", username),\\n                \\"A controlled operator username is required.\\")\\n        require(all(len(x) >= 32 and x.isascii() and not any(c.isspace() for c in x)\\n                    for x in (password, key)), \\"Separate strong runtime secrets are required.\\")\\n        require(len({password, key, api}) == 3,\\n                \\"Operator, signing, and MCP credentials must be different.\\")\\n        state = os.environ.get(\\"MAPCP_CONFIG_STATE_DIR\\", \\"\\")\\n        require(state and Path(state).is_absolute(), \\"An approved absolute state directory is required.\\")\\n        return cls(origin, username, password, key, Path(state))\\n\\n\\nclass ReviewService:\\n    def __init__(self, outputs_root, project_data_root, settings):\\n        self.outputs = Path(outputs_root).resolve()\\n        self.data = Path(project_data_root).resolve()\\n        self.settings = settings\\n\\n    def _db(self, create=False):\\n        directory = self.settings.state_dir\\n        if create:\\n            directory.mkdir(mode=0o700, parents=True, exist_ok=True)\\n        require(directory.is_dir() and not directory.is_symlink(),\\n                \\"Review state storage is unavailable.\\")\\n        path = directory / \\"configuration_reviews.sqlite3\\"\\n        require(not path.is_symlink(), \\"Review state must not be a symlink.\\")\\n        if not create:\\n            require(path.is_file(), \\"Review state is unavailable.\\")\\n        db = sqlite3.connect(path, timeout=5, isolation_level=None)\\n        db.row_factory = sqlite3.Row\\n        if create:\\n            db.execute(\\"\\"\\"CREATE TABLE IF NOT EXISTS reviews (\\n                id TEXT PRIMARY KEY, payload TEXT NOT NULL, result TEXT NOT NULL,\\n                result_digest TEXT NOT NULL, expires REAL NOT NULL,\\n                state TEXT NOT NULL, configuration_id TEXT,\\n                crosswalk_digest TEXT, record_digest TEXT)\\"\\"\\")\\n        return db\\n\\n    def _review(self, payload):\\n        request = SourceReviewRequest.model_validate(payload)\\n        result = review_source_configuration(self.outputs, self.data, request)\\n        require(result.get(\\"status\\") == \\"draft_review_complete_requires_human_review\\",\\n                \\"Source review failed; no configuration saved.\\")\\n        require(len(canonical(result).encode()) <= MAX_BYTES,\\n                \\"Review exceeds the size limit.\\")\\n        return result\\n\\n    def request_review(self, payload):\\n        request = SourceReviewRequest.model_validate(payload)\\n        payload = request.model_dump(mode=\\"json\\")\\n        require(len(canonical(payload).encode()) <= MAX_BYTES, \\"Request too large.\\")\\n        result = self._review(payload)\\n        review_id = \\"cr_\\" + secrets.token_hex(16)\\n        expires = time.time() + TTL_SECONDS\\n        db = self._db(create=True)\\n        try:\\n            db.execute(\\"BEGIN IMMEDIATE\\")\\n            require(db.execute(\\"SELECT count(*) FROM reviews\\").fetchone()[0] < MAX_REVIEWS,\\n                    \\"Review capacity reached; administrator review required. Nothing pruned.\\")\\n            db.execute(\\"INSERT INTO reviews VALUES (?,?,?,?,?,\'pending\',NULL,NULL,NULL)\\",\\n                       (review_id, canonical(payload), canonical(result), digest(result), expires))\\n            db.commit()\\n        except Exception:\\n            db.rollback()\\n            raise\\n        finally:\\n            db.close()\\n        return {\\"status\\": \\"human_browser_review_required\\", \\"review_id\\": review_id,\\n                \\"review_url\\": self.settings.origin + \\"/configuration-review/\\" + review_id,\\n                \\"expires_at_utc\\": datetime.fromtimestamp(expires, timezone.utc).isoformat(),\\n                \\"review_sha256\\": result[\\"review\\"][\\"review_sha256\\"],\\n                \\"configuration_saved\\": False,\\n                \\"warnings\\": [\\"Operator authentication is required; the link does not authorize approval.\\",\\n                             \\"Approval saves only this crosswalk; it does not authorize mapping.\\"]}\\n\\n    def row(self, review_id):\\n        require(isinstance(review_id, str) and ID.fullmatch(review_id), \\"Invalid review ID.\\")\\n        db = self._db()\\n        try:\\n            row = db.execute(\\"SELECT * FROM reviews WHERE id=?\\", (review_id,)).fetchone()\\n            require(row is not None, \\"Review not found.\\")\\n            value = dict(row)\\n            require(digest(json.loads(value[\\"result\\"])) == value[\\"result_digest\\"],\\n                    \\"Stored review changed.\\")\\n            return value\\n        finally:\\n            db.close()\\n\\n    def status(self, review_id):\\n        row = self.row(review_id)\\n        state = row[\\"state\\"]\\n        if state == \\"pending\\" and time.time() >= row[\\"expires\\"]:\\n            state = \\"expired\\"\\n        answer = {\\"status\\": state, \\"review_id\\": review_id,\\n                  \\"configuration_saved\\": state == \\"approved\\"}\\n        if state == \\"approved\\":\\n            crosswalk = local._read(self.data / \\"run_crosswalks\\" / row[\\"configuration_id\\"])\\n            record = local._read(self.data / \\"approvals\\" / crosswalk[\\"approval_record_filename\\"])\\n            self.validate(crosswalk, record)\\n            answer.update(configuration_id=row[\\"configuration_id\\"],\\n                          crosswalk_filename=row[\\"configuration_id\\"],\\n                          acquisition_directory=json.loads(row[\\"payload\\"])[\\"acquisition_directory\\"],\\n                          classification_performed=False)\\n        return answer\\n\\n    def csrf(self, row):\\n        message = \\"csrf:\\" + row[\\"id\\"] + \\":\\" + row[\\"result_digest\\"]\\n        return hmac.new(self.settings.signing_key.encode(), message.encode(), hashlib.sha256).hexdigest()\\n\\n    def _signature(self, record):\\n        payload = {k: v for k, v in record.items() if k != \\"browser_signature\\"}\\n        return hmac.new(self.settings.signing_key.encode(), canonical(payload).encode(), hashlib.sha256).hexdigest()\\n\\n    def decide(self, review_id, choice, csrf):\\n        require(choice in {\\"approve\\", \\"reject\\"}, \\"Explicit approve or reject required.\\")\\n        initial = self.row(review_id)\\n        require(isinstance(csrf, str) and hmac.compare_digest(csrf, self.csrf(initial)), \\"Invalid form token.\\")\\n        db = self._db()\\n        try:\\n            db.execute(\\"BEGIN IMMEDIATE\\")\\n            row = dict(db.execute(\\"SELECT * FROM reviews WHERE id=?\\", (review_id,)).fetchone())\\n            require(row[\\"state\\"] == \\"pending\\", \\"Review already decided; replay refused.\\")\\n            require(time.time() < row[\\"expires\\"], \\"Review expired; request a new review.\\")\\n            if choice == \\"reject\\":\\n                db.execute(\\"UPDATE reviews SET state=\'rejected\' WHERE id=?\\", (review_id,))\\n                db.commit()\\n                return {\\"status\\": \\"rejected\\", \\"configuration_saved\\": False}\\n            result = self._review(json.loads(row[\\"payload\\"]))\\n            require(digest(result) == row[\\"result_digest\\"],\\n                    \\"Inputs or review changed; request a new review. No configuration saved.\\")\\n            require(time.time() < row[\\"expires\\"], \\"Review expired during validation.\\")\\n            for dirname in (\\"run_crosswalks\\", \\"approvals\\"):\\n                target_dir = self.data / dirname\\n                require(not target_dir.is_symlink() and target_dir.resolve().parent == self.data,\\n                        \\"Configuration directory is not controlled.\\")\\n            key = \\"review_\\" + review_id[3:]\\n            name, cw, record_name, record = local._build_documents(result, key, \\"v1\\")\\n            cw.pop(\\"approval_record_sha256\\", None)\\n            cw[\\"crosswalk_approval_note\\"] = (\\n                \\"Exact project-specific review accepted by the configured prototype operator \\"\\n                \\"through the authenticated browser. Not Tribal approval or legal authority.\\")\\n            record[\\"schema\\"] = SCHEMA\\n            record.pop(\\"operator_confirmation_recorded\\", None)\\n            record.pop(\\"identity_authenticated\\", None)\\n            record[\\"approval_method\\"] = \\"separate_operator_authenticated_browser\\"\\n            record[\\"browser_review_id\\"] = review_id\\n            record[\\"browser_review_digest\\"] = row[\\"result_digest\\"]\\n            record[\\"browser_operator\\"] = self.settings.username\\n            record[\\"accepted_at_utc\\"] = datetime.now(timezone.utc).isoformat()\\n            record[\\"crosswalk_payload_sha256\\"] = digest(cw)\\n            record[\\"browser_signature\\"] = self._signature(record)\\n            cw[\\"approval_record_sha256\\"] = digest(record)\\n            # The approved DB marker is committed only after both files read back.\\n            # A storage failure can leave files, but never an approved marker.\\n            try:\\n                local._write_documents(self.data, name, cw, record_name, record)\\n                require(local._read(self.data / \\"run_crosswalks\\" / name) == cw\\n                        and local._read(self.data / \\"approvals\\" / record_name) == record,\\n                        \\"Configuration read-back failed.\\")\\n            except Exception:\\n                db.execute(\\"UPDATE reviews SET state=\'failed_storage\' WHERE id=?\\", (review_id,))\\n                db.commit()\\n                raise ReviewError(\\"Storage failed; incomplete files may remain. Administrator review required.\\") from None\\n            db.execute(\\"\\"\\"UPDATE reviews SET state=\'approved\', configuration_id=?,\\n                          crosswalk_digest=?, record_digest=? WHERE id=?\\"\\"\\",\\n                       (name, digest(cw), digest(record), review_id))\\n            db.commit()\\n            return {\\"status\\": \\"approved\\", \\"configuration_saved\\": True,\\n                    \\"configuration_id\\": name, \\"crosswalk_filename\\": name,\\n                    \\"classification_performed\\": False}\\n        except Exception:\\n            db.rollback()\\n            raise\\n        finally:\\n            db.close()\\n\\n    def validate(self, crosswalk, record):\\n        require(record.get(\\"schema\\") == SCHEMA, \\"Unsupported browser approval schema.\\")\\n        signature = record.get(\\"browser_signature\\")\\n        require(isinstance(signature, str) and hmac.compare_digest(signature, self._signature(record)),\\n                \\"Browser approval signature invalid.\\")\\n        row = self.row(record.get(\\"browser_review_id\\"))\\n        require(row[\\"state\\"] == \\"approved\\", \\"Browser approval is not committed.\\")\\n        require(row[\\"configuration_id\\"] == record.get(\\"crosswalk_filename\\")\\n                and row[\\"crosswalk_digest\\"] == digest(crosswalk)\\n                and row[\\"record_digest\\"] == digest(record)\\n                and row[\\"result_digest\\"] == record.get(\\"browser_review_digest\\"),\\n                \\"Browser-approved configuration changed.\\")\\n\\n\\ndef runtime_service(outputs_root=None, project_data_root=None):\\n    root = Path(__file__).resolve().parent\\n    return ReviewService(outputs_root or root / \\"outputs\\",\\n                         project_data_root or root / \\"project_data\\", Settings.from_env())\\n\\n\\ndef validate_browser_approval(project_data_root, crosswalk, record):\\n    runtime_service(project_data_root=project_data_root).validate(crosswalk, record)\\n\\n\\ndef _auth(request, settings):\\n    # Browser endpoints use independent HTTP Basic credentials over HTTPS only.\\n    if request.url.scheme != \\"https\\" or str(request.url).split(\\"/configuration-review/\\", 1)[0] != settings.origin:\\n        return Response(\\"HTTPS review origin mismatch.\\", status_code=403, headers=HEADERS)\\n    now = time.monotonic()\\n    peer = request.client.host if request.client else \\"unknown\\"\\n    with _rate_lock:\\n        for key in list(_failures):\\n            if now - _failures[key][0] >= 300:\\n                del _failures[key]\\n        entry = _failures.get(peer, (now, 0))\\n        if entry[1] >= 10 or (peer not in _failures and len(_failures) >= 1024):\\n            return Response(\\"Too many authentication attempts.\\", status_code=429, headers=HEADERS)\\n    values = request.headers.getlist(\\"authorization\\")\\n    expected = base64.b64encode((settings.username + \\":\\" + settings.password).encode()).decode()\\n    valid = len(values) == 1 and hmac.compare_digest(values[0].encode(), (\\"Basic \\" + expected).encode())\\n    if not valid:\\n        with _rate_lock:\\n            _failures[peer] = (entry[0], entry[1] + 1)\\n        return Response(\\"Operator authentication required.\\", status_code=401,\\n                        headers={**HEADERS, \\"WWW-Authenticate\\": \'Basic realm=\\"MapCP configuration review\\", charset=\\"UTF-8\\"\'})\\n    return None\\n\\n\\ndef _page(service, row):\\n    result = json.loads(row[\\"result\\"])\\n    e = lambda x: html.escape(str(x), quote=True)\\n    proposal = result[\\"proposal\\"]\\n    classes = {x[\\"output_code\\"]: x[\\"label\\"] for x in proposal[\\"classes\\"]}\\n    names = {x[\\"source_evt_code\\"]: x.get(\\"official_name\\", \\"Unknown\\")\\n             for x in result[\\"source_configuration\\"][\\"entries\\"]}\\n    rows = []\\n    for x in proposal[\\"decisions\\"]:\\n        rows.append(\\"<tr>\\" + \\"\\".join(\\"<td>\\" + e(v) + \\"</td>\\" for v in (\\n            x[\\"source_evt_code\\"], names.get(x[\\"source_evt_code\\"], \\"Unknown\\"),\\n            x[\\"output_code\\"], classes[x[\\"output_code\\"]],\\n            {True: \\"true\\", False: \\"false\\", None: \\"unknown\\"}[x[\\"proposed_forest_land\\"]],\\n            x[\\"rationale\\"], \\"; \\".join(x[\\"unresolved\\"]))) + \\"</tr>\\")\\n    state = row[\\"state\\"] if time.time() < row[\\"expires\\"] else (\\n        \\"expired\\" if row[\\"state\\"] == \\"pending\\" else row[\\"state\\"])\\n    form = \\"\\"\\n    if state == \\"pending\\":\\n        form = (\'<form method=\\"post\\"><input type=\\"hidden\\" name=\\"csrf\\" value=\\"\'\\n                + e(service.csrf(row)) + \'\\"><p>No option is selected by default.</p>\'\\n                \'<button name=\\"decision\\" value=\\"approve\\" type=\\"submit\\">Approve and save this exact crosswalk</button> \'\\n                \'<button name=\\"decision\\" value=\\"reject\\" type=\\"submit\\">Reject without saving a configuration</button></form>\')\\n    return (\'<!doctype html><html><head><meta charset=\\"utf-8\\"><title>MapCP crosswalk review</title></head><body>\'\\n            \'<h1>Project-specific crosswalk review</h1><p>Preliminary planning only. \'\\n            \'Approval is not Tribal approval, geographic authority, or permission to run mapping.</p>\'\\n            \'<p>Close this page or cancel authentication if you do not wish to proceed. \'\\n            \'Use a private browser window on a trusted workstation; close it when finished.</p>\'\\n            \'<p>Review: \' + e(row[\\"id\\"]) + \' | State: \' + e(state) + \'</p>\'\\n            \'<p>Acquisition: \' + e(result[\\"acquisition_directory\\"]) + \'</p>\'\\n            \'<p>Review digest: \' + e(result[\\"review\\"][\\"review_sha256\\"]) + \'</p>\'\\n            \'<h2>Assignments</h2><table border=\\"1\\"><thead><tr>\'\\n            \'<th>EVT</th><th>Official source label</th><th>Output code</th><th>Candidate class</th>\'\\n            \'<th>Forest land</th><th>Rationale</th><th>Unresolved</th></tr></thead><tbody>\'\\n            + \'\'.join(rows) + \'</tbody></table><h2>Complete reviewed evidence</h2>\'\\n            \'<p>Includes acreage, run binding, source evidence, and limitations. \'\\n            \'Unknown is not nonforest. NoData is not nonforest.</p><pre>\'\\n            + e(json.dumps(result, indent=2, ensure_ascii=True, allow_nan=False))\\n            + \'</pre>\' + form + \'</body></html>\')\\n\\n\\nasync def browser_review(request, outputs_root=None, project_data_root=None):\\n    if os.environ.get(\\"MAPCP_CONFIG_REVIEW_ENABLED\\") != \\"true\\":\\n        return Response(\\"Not found\\", status_code=404, headers=HEADERS)\\n    try:\\n        service = runtime_service(outputs_root, project_data_root)\\n    except Exception:\\n        return Response(\\"Review service unavailable; administrator configuration required.\\",\\n                        status_code=503, headers=HEADERS)\\n    denied = _auth(request, service.settings)\\n    if denied is not None:\\n        return denied\\n    review_id = request.path_params[\\"review_id\\"]\\n    try:\\n        if request.method in {\\"GET\\", \\"HEAD\\"}:\\n            row = await run_in_threadpool(service.row, review_id)\\n            return HTMLResponse(_page(service, row), headers=HEADERS)\\n        require(request.headers.get(\\"origin\\") == service.settings.origin,\\n                \\"Approval origin mismatch.\\")\\n        require(request.headers.get(\\"content-type\\", \\"\\").split(\\";\\", 1)[0]\\n                == \\"application/x-www-form-urlencoded\\", \\"Unsupported form content type.\\")\\n        body = bytearray()\\n        async for chunk in request.stream():\\n            body.extend(chunk)\\n            require(len(body) <= 2048, \\"Form too large.\\")\\n        form = parse_qs(body.decode(\\"ascii\\"), strict_parsing=True, max_num_fields=2)\\n        require(set(form) == {\\"csrf\\", \\"decision\\"} and all(len(v) == 1 for v in form.values()),\\n                \\"Invalid approval form.\\")\\n        result = await run_in_threadpool(service.decide, review_id,\\n                                        form[\\"decision\\"][0], form[\\"csrf\\"][0])\\n        return HTMLResponse(\'<!doctype html><html><body><h1>MapCP review result</h1><pre>\'\\n                            + html.escape(json.dumps(result, indent=2))\\n                            + \'</pre><p>Return to Orchestrate and ask it to check the review status. \'\\n                            \'No mapping was performed.</p></body></html>\', headers=HEADERS)\\n    except ReviewError:\\n        return Response(\\"Review refused or unavailable. Check status in Orchestrate. \\"\\n                        \\"Storage failures may require administrator review; do not retry blindly.\\",\\n                        status_code=409, headers=HEADERS)\\n    except Exception:\\n        return Response(\\"Review failed. Do not assume a configuration was saved; \\"\\n                        \\"administrator review may be required.\\", status_code=503, headers=HEADERS)\\n\\n\\ndef browser_routes(outputs_root=None, project_data_root=None):\\n    async def endpoint(request):\\n        return await browser_review(request, outputs_root, project_data_root)\\n    return [Route(\\"/configuration-review/{review_id}\\", endpoint, methods=[\\"GET\\", \\"POST\\"])]\\n", "configuration_browser_mcp.py": "\\"\\"\\"Register request/status only. No MCP operation can approve a review.\\"\\"\\"\\nfrom pydantic import BaseModel, ConfigDict, Field\\nfrom configuration_browser import runtime_service\\nfrom source_configuration_workflow import SourceReviewRequest\\n\\n\\nclass ConfigurationReviewStatusRequest(BaseModel):\\n    model_config = ConfigDict(extra=\\"forbid\\", strict=True)\\n    review_id: str = Field(pattern=r\\"^cr_[0-9a-f]{32}$\\")\\n\\n\\ndef register_configuration_browser_tools(mcp, outputs_root, project_data_root):\\n    @mcp.tool()\\n    def request_candidate_configuration_review(request: SourceReviewRequest) -> dict:\\n        \\"\\"\\"Prepare an expiring browser review of this exact project-specific crosswalk.\\n\\n        Consequential local state write: obtain permission before requesting.\\n        No default pilot crosswalk. Rebuilds actual source/proposal/acreage review.\\n        Returns a review ID and controlled HTTPS page, not an approved crosswalk.\\n        Human operator must authenticate separately in their browser. Never ask\\n        for the operator credential in chat. Opening the URL does not approve.\\n        Does not save a crosswalk, classify, download, map, polygonize, or export.\\n        Disabled unless storage and independent operator authentication configured.\\n        \\"\\"\\"\\n        try:\\n            return runtime_service(outputs_root, project_data_root).request_review(\\n                request.model_dump(mode=\\"json\\"))\\n        except Exception:\\n            return {\\"status\\": \\"review_request_failed\\", \\"configuration_saved\\": False,\\n                    \\"error\\": \\"Review unavailable, invalid, disabled, or capacity reached. No configuration approved.\\"}\\n\\n    @mcp.tool()\\n    def check_candidate_configuration_review(request: ConfigurationReviewStatusRequest) -> dict:\\n        \\"\\"\\"Read a browser review\'s state using its exact returned review ID.\\n\\n        No approval, save, mapping, or export. Approved status validates saved\\n        configuration and approval evidence before returning configuration_id.\\n        That ID is the controlled JSON filename accepted by the existing mapping\\n        tool\'s required crosswalk_filename field. Carry it exactly; do not guess.\\n        Mapping needs separate applicable authorization and a matching acquisition.\\n        \\"\\"\\"\\n        try:\\n            return runtime_service(outputs_root, project_data_root).status(request.review_id)\\n        except Exception:\\n            return {\\"status\\": \\"review_status_failed\\", \\"configuration_saved\\": False,\\n                    \\"error\\": \\"Review unavailable or saved evidence failed validation. Do not map.\\"}\\n", "tests/test_configuration_browser.py": "\\"\\"\\"Synthetic review tests. No real operator, source raster, or cloud service.\\"\\"\\"\\nimport base64\\nimport copy\\nimport hashlib\\nfrom pathlib import Path\\n\\nimport pytest\\nfrom starlette.applications import Starlette\\nfrom starlette.testclient import TestClient\\n\\nimport configuration_browser as cb\\nimport boundary_mapping as bm\\nfrom source_configuration import build_source_configuration\\nfrom crosswalk_proposal import build_crosswalk_proposal\\nfrom crosswalk_review import build_crosswalk_review\\n\\n\\n@pytest.fixture\\ndef setup(tmp_path, monkeypatch):\\n    data = b\\"VALUE,NAME\\\\n10,Synthetic tree\\\\n\\"\\n    profile = {\\"product\\": \\"EVT\\", \\"version\\": \\"synthetic\\", \\"region\\": \\"CONUS\\"}\\n    source = build_source_configuration(\\n        data, [10, 40], raster_profile=profile,\\n        catalog_record={**profile, \\"source_url\\": \\"https://www.landfire.gov/synthetic.csv\\",\\n                        \\"sha256\\": hashlib.sha256(data).hexdigest()},\\n        code_column=\\"VALUE\\", name_column=\\"NAME\\")\\n    proposal = build_crosswalk_proposal(source, {\\n        \\"source_configuration_sha256\\": source[\\"configuration_sha256\\"],\\n        \\"classes\\": [\\n            {\\"output_code\\": 10, \\"label\\": \\"synthetic_tree\\", \\"rationale\\": \\"Synthetic only\\"},\\n            {\\"output_code\\": 40, \\"label\\": \\"unknown_40\\", \\"rationale\\": \\"Preserve unknown\\"}],\\n        \\"decisions\\": [\\n            {\\"source_evt_code\\": 10, \\"output_code\\": 10, \\"proposed_forest_land\\": True,\\n             \\"rationale\\": \\"Synthetic only\\", \\"unresolved\\": []},\\n            {\\"source_evt_code\\": 40, \\"output_code\\": 40, \\"proposed_forest_land\\": None,\\n             \\"rationale\\": \\"Unknown remains unknown\\", \\"unresolved\\": [\\"Missing official label\\"]}]})\\n    evidence = {\\n        \\"source_run_id\\": \\"bacq_synthetic\\", \\"boundary_sha256\\": \\"a\\" * 64,\\n        \\"source_raster_sha256\\": \\"b\\" * 64,\\n        \\"source_configuration_sha256\\": source[\\"configuration_sha256\\"],\\n        \\"proposal_sha256\\": proposal[\\"proposal_sha256\\"], \\"total_grid_cells\\": 3,\\n        \\"outside_boundary_cells\\": 0, \\"evt_nodata_inside_boundary_cells\\": 1,\\n        \\"evt_counts\\": [{\\"source_evt_code\\": 10, \\"cell_count\\": 1},\\n                       {\\"source_evt_code\\": 40, \\"cell_count\\": 1}]}\\n    result = {\\"status\\": \\"draft_review_complete_requires_human_review\\",\\n              \\"acquisition_directory\\": \\"bacq_synthetic\\", \\"source_configuration\\": source,\\n              \\"proposal\\": proposal, \\"review\\": build_crosswalk_review(source, proposal, evidence),\\n              \\"limitations\\": [\\"Synthetic only; not actual forestry approval\\"]}\\n    settings = cb.Settings(\\"https://review.example.test\\", \\"operator\\", \\"p\\" * 48,\\n                           \\"s\\" * 48, tmp_path / \\"state\\")\\n    service = cb.ReviewService(tmp_path / \\"outputs\\", tmp_path / \\"data\\", settings)\\n    monkeypatch.setattr(cb, \\"review_source_configuration\\", lambda *args: copy.deepcopy(result))\\n    monkeypatch.setattr(cb, \\"runtime_service\\", lambda *args, **kwargs: service)\\n    monkeypatch.setenv(\\"MAPCP_CONFIG_REVIEW_ENABLED\\", \\"true\\")\\n    cb._failures.clear()\\n    return service, result\\n\\n\\ndef pending(service):\\n    return service.request_review({\\"acquisition_directory\\": \\"bacq_synthetic\\", \\"proposal\\": None})\\n\\n\\ndef approve(service, review_id):\\n    return service.decide(review_id, \\"approve\\", service.csrf(service.row(review_id)))\\n\\n\\ndef test_request_and_get_do_not_save_configuration(setup):\\n    service, _ = setup\\n    result = pending(service)\\n    assert result[\\"configuration_saved\\"] is False\\n    assert not (service.data / \\"run_crosswalks\\").exists()\\n    app = Starlette(routes=cb.browser_routes())\\n    with TestClient(app, base_url=service.settings.origin) as client:\\n        response = client.get(\\"/configuration-review/\\" + result[\\"review_id\\"],\\n                              auth=(service.settings.username, service.settings.password))\\n    assert response.status_code == 200\\n    assert \\"unknown_40\\" in response.text\\n    assert \\"Complete reviewed evidence\\" in response.text\\n    assert not (service.data / \\"run_crosswalks\\").exists()\\n\\n\\ndef test_approve_real_documents_and_mapping_validation(setup):\\n    service, _ = setup\\n    review_id = pending(service)[\\"review_id\\"]\\n    saved = approve(service, review_id)\\n    assert saved[\\"configuration_saved\\"] is True\\n    assert saved[\\"classification_performed\\"] is False\\n    cw, _ = bm.load_crosswalk(service.data, saved[\\"configuration_id\\"])\\n    assert next(e for e in cw[\\"entries\\"] if e[\\"evt_code\\"] == 40)[\\"candidate_forest_land\\"] is None\\n    cb.local.validate_run_binding(service.data, \\"bacq_synthetic\\", {\\n        \\"boundary_sha256\\": \\"a\\" * 64, \\"extract\\": {\\"geotiff_sha256\\": \\"b\\" * 64}}, cw)\\n    assert service.status(review_id)[\\"configuration_id\\"] == saved[\\"configuration_id\\"]\\n\\n\\ndef test_rejection_no_configuration(setup):\\n    service, _ = setup\\n    review_id = pending(service)[\\"review_id\\"]\\n    result = service.decide(review_id, \\"reject\\", service.csrf(service.row(review_id)))\\n    assert result[\\"status\\"] == \\"rejected\\"\\n    assert not (service.data / \\"run_crosswalks\\").exists()\\n\\n\\ndef test_changed_review_no_configuration(setup, monkeypatch):\\n    service, original = setup\\n    review_id = pending(service)[\\"review_id\\"]\\n    changed = copy.deepcopy(original)\\n    changed[\\"limitations\\"].append(\\"Changed\\")\\n    monkeypatch.setattr(cb, \\"review_source_configuration\\", lambda *args: changed)\\n    with pytest.raises(cb.ReviewError, match=\\"changed\\"):\\n        approve(service, review_id)\\n    assert not (service.data / \\"run_crosswalks\\").exists()\\n\\n\\ndef test_expired_request_no_configuration(setup, monkeypatch):\\n    service, _ = setup\\n    review_id = pending(service)[\\"review_id\\"]\\n    expires = service.row(review_id)[\\"expires\\"]\\n    monkeypatch.setattr(cb.time, \\"time\\", lambda: expires + 1)\\n    with pytest.raises(cb.ReviewError, match=\\"expired\\"):\\n        approve(service, review_id)\\n    assert not (service.data / \\"run_crosswalks\\").exists()\\n\\n\\ndef test_replay_refused(setup):\\n    service, _ = setup\\n    review_id = pending(service)[\\"review_id\\"]\\n    approve(service, review_id)\\n    with pytest.raises(cb.ReviewError, match=\\"replay\\"):\\n        approve(service, review_id)\\n\\n\\ndef test_wrong_run_and_tampered_record_refused(setup):\\n    service, _ = setup\\n    saved = approve(service, pending(service)[\\"review_id\\"])\\n    cw, _ = bm.load_crosswalk(service.data, saved[\\"configuration_id\\"])\\n    with pytest.raises(ValueError, match=\\"does not match\\"):\\n        cb.local.validate_run_binding(service.data, \\"bacq_different\\", {\\n            \\"boundary_sha256\\": \\"a\\" * 64, \\"extract\\": {\\"geotiff_sha256\\": \\"b\\" * 64}}, cw)\\n    record = cb.local._read(service.data / \\"approvals\\" / cw[\\"approval_record_filename\\"])\\n    record[\\"browser_operator\\"] = \\"forged\\"\\n    with pytest.raises(cb.ReviewError, match=\\"signature\\"):\\n        service.validate(cw, record)\\n\\n\\ndef test_bad_form_token_no_configuration(setup):\\n    service, _ = setup\\n    review_id = pending(service)[\\"review_id\\"]\\n    with pytest.raises(cb.ReviewError, match=\\"form token\\"):\\n        service.decide(review_id, \\"approve\\", \\"forged\\")\\n    assert not (service.data / \\"run_crosswalks\\").exists()\\n\\n\\ndef test_bearer_and_unauthenticated_browser_cannot_approve(setup):\\n    service, _ = setup\\n    review_id = pending(service)[\\"review_id\\"]\\n    path = \\"/configuration-review/\\" + review_id\\n    with TestClient(Starlette(routes=cb.browser_routes()), base_url=service.settings.origin) as client:\\n        assert client.get(path).status_code == 401\\n        response = client.post(path, headers={\\"Authorization\\": \\"Bearer \\" + \\"a\\" * 48,\\n                                              \\"Origin\\": service.settings.origin},\\n                               data={\\"decision\\": \\"approve\\", \\"csrf\\": service.csrf(service.row(review_id))})\\n    assert response.status_code == 401\\n    assert not (service.data / \\"run_crosswalks\\").exists()\\n\\n\\ndef test_browser_origin_csrf_and_http_denied(setup):\\n    service, _ = setup\\n    review_id = pending(service)[\\"review_id\\"]\\n    path = \\"/configuration-review/\\" + review_id\\n    auth = (service.settings.username, service.settings.password)\\n    with TestClient(Starlette(routes=cb.browser_routes()), base_url=service.settings.origin) as client:\\n        assert client.post(path, auth=auth, headers={\\"Origin\\": \\"https://other.example\\"},\\n                           data={\\"decision\\": \\"approve\\", \\"csrf\\": service.csrf(service.row(review_id))}).status_code == 409\\n        assert client.post(path, auth=auth, headers={\\"Origin\\": service.settings.origin},\\n                           data={\\"decision\\": \\"approve\\", \\"csrf\\": \\"wrong\\"}).status_code == 409\\n        assert client.get(\\"http://review.example.test\\" + path, auth=auth).status_code == 403\\n    assert not (service.data / \\"run_crosswalks\\").exists()\\n\\n\\ndef test_real_browser_approval_post(setup):\\n    service, _ = setup\\n    review_id = pending(service)[\\"review_id\\"]\\n    with TestClient(Starlette(routes=cb.browser_routes()), base_url=service.settings.origin) as client:\\n        response = client.post(\\"/configuration-review/\\" + review_id,\\n                               auth=(service.settings.username, service.settings.password),\\n                               headers={\\"Origin\\": service.settings.origin},\\n                               data={\\"decision\\": \\"approve\\", \\"csrf\\": service.csrf(service.row(review_id))})\\n    assert response.status_code == 200\\n    assert service.status(review_id)[\\"configuration_saved\\"] is True\\n\\n\\ndef test_partial_write_is_not_approved(setup, monkeypatch):\\n    service, _ = setup\\n    review_id = pending(service)[\\"review_id\\"]\\n    def broken_writer(root, name, cw, record_name, record):\\n        directory = Path(root) / \\"approvals\\"\\n        directory.mkdir(parents=True)\\n        (directory / record_name).write_text(cb.canonical(record))\\n        raise OSError(\\"SIMULATED storage failure\\")\\n    monkeypatch.setattr(cb.local, \\"_write_documents\\", broken_writer)\\n    with pytest.raises(cb.ReviewError, match=\\"incomplete files\\"):\\n        approve(service, review_id)\\n    assert service.status(review_id)[\\"status\\"] == \\"failed_storage\\"\\n    assert not (service.data / \\"run_crosswalks\\").exists()\\n\\n\\ndef test_disabled_http_and_runtime_settings(setup, monkeypatch):\\n    service, _ = setup\\n    monkeypatch.delenv(\\"MAPCP_CONFIG_REVIEW_ENABLED\\", raising=False)\\n    with pytest.raises(cb.ReviewError, match=\\"disabled\\"):\\n        cb.Settings.from_env()\\n    with TestClient(Starlette(routes=cb.browser_routes()), base_url=service.settings.origin) as client:\\n        assert client.get(\\"/configuration-review/cr_\\" + \\"0\\" * 32).status_code == 404\\n\\n\\ndef test_state_survives_service_recreation(setup):\\n    service, _ = setup\\n    review_id = pending(service)[\\"review_id\\"]\\n    saved = approve(service, review_id)\\n    recreated = cb.ReviewService(service.outputs, service.data, service.settings)\\n    assert recreated.status(review_id)[\\"configuration_id\\"] == saved[\\"configuration_id\\"]\\n\\n\\ndef test_outer_bearer_guard_preserved_and_browser_independently_protected(setup):\\n    # Isolates the actual middleware class to avoid importing the GIS MCP server.\\n    import ast\\n    import secrets\\n    from starlette.responses import JSONResponse\\n    from starlette.routing import Route\\n    service, _ = setup\\n    path = Path(__file__).resolve().parents[1] / \\"server_http.py\\"\\n    tree = ast.parse(path.read_text())\\n    node = next(n for n in tree.body if isinstance(n, ast.ClassDef)\\n                and n.name == \\"RequireBearerToken\\")\\n    namespace = {\\"secrets\\": secrets, \\"JSONResponse\\": JSONResponse}\\n    exec(compile(ast.Module(body=[node], type_ignores=[]), str(path), \\"exec\\"), namespace)\\n    async def ok(request):\\n        return JSONResponse({\\"ok\\": True})\\n    app = Starlette(routes=cb.browser_routes() + [\\n        Route(\\"/health\\", ok), Route(\\"/mcp\\", ok)])\\n    protected = namespace[\\"RequireBearerToken\\"](app, \\"a\\" * 48)\\n    review_id = pending(service)[\\"review_id\\"]\\n    with TestClient(protected, base_url=service.settings.origin) as client:\\n        assert client.get(\\"/health\\").status_code == 200\\n        assert client.get(\\"/mcp\\").status_code == 401\\n        assert client.get(\\"/mcp\\", headers={\\"Authorization\\": \\"Bearer \\" + \\"a\\" * 48}).status_code == 200\\n        assert client.get(\\"/configuration-review/\\" + review_id).status_code == 401\\n        assert client.get(\\"/configuration-review/\\" + review_id,\\n                          auth=(service.settings.username, service.settings.password)).status_code == 200\\n\\n\\ndef test_expiry_during_fresh_review_no_configuration(setup, monkeypatch):\\n    service, original = setup\\n    review_id = pending(service)[\\"review_id\\"]\\n    expires = service.row(review_id)[\\"expires\\"]\\n    def slow_review(*args):\\n        monkeypatch.setattr(cb.time, \\"time\\", lambda: expires + 1)\\n        return copy.deepcopy(original)\\n    monkeypatch.setattr(cb, \\"review_source_configuration\\", slow_review)\\n    with pytest.raises(cb.ReviewError, match=\\"expired during\\"):\\n        approve(service, review_id)\\n    assert not (service.data / \\"run_crosswalks\\").exists()\\n\\n\\ndef test_pending_capacity_no_automatic_pruning(setup, monkeypatch):\\n    service, _ = setup\\n    monkeypatch.setattr(cb, \\"MAX_REVIEWS\\", 1)\\n    review_id = pending(service)[\\"review_id\\"]\\n    with pytest.raises(cb.ReviewError, match=\\"capacity\\"):\\n        pending(service)\\n    assert service.status(review_id)[\\"status\\"] == \\"pending\\"\\n\\n\\ndef test_signing_key_change_refuses_saved_approval(setup):\\n    service, _ = setup\\n    review_id = pending(service)[\\"review_id\\"]\\n    saved = approve(service, review_id)\\n    settings = cb.Settings(service.settings.origin, service.settings.username,\\n                           service.settings.password, \\"different\\" * 8,\\n                           service.settings.state_dir)\\n    changed = cb.ReviewService(service.outputs, service.data, settings)\\n    cw, _ = bm.load_crosswalk(service.data, saved[\\"configuration_id\\"])\\n    record = cb.local._read(service.data / \\"approvals\\" / cw[\\"approval_record_filename\\"])\\n    with pytest.raises(cb.ReviewError, match=\\"signature\\"):\\n        changed.validate(cw, record)\\n\\n\\ndef test_review_id_path_rejected(setup):\\n    service, _ = setup\\n    with pytest.raises(cb.ReviewError, match=\\"Invalid review ID\\"):\\n        service.status(\\"../../other\\")\\n"}')


def once(text, old, new, label):
    if text.count(old) != 1:
        raise SystemExit("Refusing patch: expected exactly one anchor for " + label)
    return text.replace(old, new, 1)


def section(text, start, end, replacement, label):
    if text.count(start) != 1 or text.count(end) != 1:
        raise SystemExit("Refusing patch: section anchors differ for " + label)
    a = text.index(start)
    b = text.index(end, a)
    return text[:a] + replacement + text[b:]


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--repo", type=Path, default=Path.cwd())
    parser.add_argument("--apply", action="store_true")
    args = parser.parse_args()
    root = args.repo.resolve()
    def git(*parts):
        return subprocess.check_output(["git", "-C", str(root), *parts], text=True).strip()
    if git("rev-parse", "--short=7", "HEAD") != "aa783c9":
        raise SystemExit("Refusing patch: expected reviewed checkout aa783c9.")
    if git("status", "--porcelain"):
        raise SystemExit("Refusing patch: working tree is not clean. Preserve/review changes first.")
    changes = {}
    for name, content in NEW_FILES.items():
        path = root / name
        if path.exists():
            raise SystemExit("Refusing to overwrite existing new-file target: " + name)
        changes[name] = content
    name = "server_http.py"
    text = (root / name).read_text()
    text = once(text, "from server import mcp\n", "from server import mcp, OUTPUT_FOLDER, _PROJECT_DATA_DIR\nfrom configuration_browser import browser_routes\n", name + " import")
    text = once(text, '        public_health = (',
                '        # Only these browser routes bypass MCP bearer auth; each has its own\n'
                '        # independent HTTPS operator authentication and CSRF enforcement.\n'
                '        if scope["path"].startswith("/configuration-review/"):\n'
                '            await self.app(scope, receive, send)\n'
                '            return\n\n        public_health = (', name + " dispatch")
    text = once(text, '    return RequireBearerToken(http_app, token)',
                '    for route in reversed(browser_routes(OUTPUT_FOLDER, _PROJECT_DATA_DIR)):\n'
                '        http_app.routes.insert(0, route)\n'
                '    return RequireBearerToken(http_app, token)', name + " routes")
    changes[name] = text
    name = "server.py"
    text = (root / name).read_text()
    text = once(text, 'if __name__ == "__main__":',
                'from configuration_browser_mcp import register_configuration_browser_tools\n\n'
                'register_configuration_browser_tools(mcp, OUTPUT_FOLDER, _PROJECT_DATA_DIR)\n\n\n'
                'if __name__ == "__main__":', name + " registration")
    changes[name] = text
    name = "crosswalk_configuration_save.py"
    text = (root / name).read_text()
    old = '    _require(\n        record.get("schema") == "mapcp_local_configuration_approval_v1"\n        and record.get("operator_confirmation_recorded") is True,\n        "Missing local operator confirmation record.",\n    )'
    new = '    browser_approved = record.get("schema") == "mapcp_browser_configuration_approval_v1"\n    if browser_approved:\n        from configuration_browser import validate_browser_approval\n        validate_browser_approval(project_data_root, crosswalk, record)\n    _require(\n        browser_approved or (\n            record.get("schema") == "mapcp_local_configuration_approval_v1"\n            and record.get("operator_confirmation_recorded") is True\n        ),\n        "Missing local operator confirmation record.",\n    )'
    changes[name] = once(text, old, new, name)
    name = "boundary_mapping.py"
    text = (root / name).read_text()
    old = 'add_argument("--crosswalk", default="mescalero_v1_evt_crosswalk_v2.json")'
    if text.count(old) != 2:
        raise SystemExit("Refusing patch: expected two reviewed CLI crosswalk defaults.")
    changes[name] = text.replace(old, 'add_argument("--crosswalk", required=True)')
    name = "orchestrate/agent.yaml"
    text = (root / name).read_text()
    replacement = '  Configuration saving uses an authenticated browser review when the connected\n  request_candidate_configuration_review and check_candidate_configuration_review\n  tools are available and enabled. Obtain permission before writing a pending\n  review request. Present the exact returned review link; it is not approval.\n  The operator authenticates separately in the browser. Never request, transmit,\n  infer, or store the operator password in chat or tool inputs. No file upload\n  is required. Do not claim approval from conversational text or a Boolean.\n  Check the exact returned review ID after the user completes browser review.\n  Only approved status with successfully validated saved evidence returns the\n  actual configuration_id and crosswalk_filename. These identify the same saved\n  JSON file. Pass crosswalk_filename exactly to mapping with its matching\n  acquisition. Pending, rejected, expired, failed, or unavailable status blocks\n  mapping. No default project crosswalk and no optional crosswalk for mapping.\n  Approval saves only that configuration; mapping/export need their own applicable\n  authorization. Never expose the local CLI or a browser-approve MCP tool.\n  If browser review is disabled or unavailable, state the blocker; do not invent\n  saved IDs or claim a VM file is available in the hosted runtime.\n\n'
    text = section(text, "  Configuration saving is a LOCAL OPERATOR HANDOFF", "  For the boundary mapping path,", replacement, name)
    anchor = "- tribal_forest_mapcp_export:review_candidate_source_configuration"
    text = once(text, anchor, anchor + "\n- tribal_forest_mapcp_export:request_candidate_configuration_review\n- tribal_forest_mapcp_export:check_candidate_configuration_review", name + " tools")
    changes[name] = text
    name = "skills/candidate-cover-mapping-review/SKILL.md"
    text = (root / name).read_text()
    replacement = '5. With permission to write a pending review, use the connected\n   request_candidate_configuration_review tool with the exact reviewed proposal.\n   Present its actual review URL and review ID. The operator reviews decisions,\n   unknowns, acreage, and limitations and authenticates separately in the browser.\n   No manual file upload is required. Never request or handle the operator password\n   in chat. Opening a URL or saying yes in chat is not backend approval.\n6. Use check_candidate_configuration_review with the exact returned review ID.\n   Only an approved status with validated saved evidence permits continuing.\n   Carry its actual crosswalk_filename (also returned as configuration_id) and\n   matching acquisition into mapping. Reject/pending/expired/failed states block\n   mapping. A crosswalk is mandatory, project-specific, and never silently defaulted.\n   Approval saves the configuration only; do not infer approval to execute mapping.\n   If this hosted capability is unavailable, report the blocker honestly.\n'
    text = section(text, "5. Configuration saving remains a local operator handoff.", "7. Use preview_boundary_candidate_mapping", replacement, name)
    changes[name] = text
    for name, content in changes.items():
        if name.endswith(".py"):
            compile(content, name, "exec")
    print("Validated source anchors and Python syntax. Planned files:")
    for name in changes:
        print("  " + name)
    if not args.apply:
        print("Check-only: no files changed. Review bundle, then explicitly use --apply.")
        return
    for name, content in changes.items():
        path = root / name
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(content, encoding="utf-8")
    print("Applied source edits only. No secrets, state DB, installs, commits, pushes, or deployment.")
    print("Review git diff and run tests before enabling anything.")


if __name__ == "__main__":
    main()
